using System;
using System.IO;
using System.Collections.Generic;
using System.Web.Script.Serialization;
public static class SodaDesktopSigninMaintenanceRecoveryChecks {
 const string Owner="S-1-5-21-1-2-3-1001";
 static void Check(bool value,string message){if(!value)throw new InvalidOperationException(message);}
 static void Refused(Action action,string message){bool failed=false;try{action();}catch(InvalidOperationException){failed=true;}catch(IOException){failed=true;}Check(failed,message);}
 static string Marker(SodaDesktopSigninUpgradeChecks.Fixture f){return Path.Combine(f.Paths.Slot,"install.transition");}
 static SodaDesktopSigninUpgradeChecks.Fixture Prepare(){var f=new SodaDesktopSigninUpgradeChecks.Fixture(true);try{Refused(()=>f.Run(step=>{if(step=="marker-written")f.Active=false;}),"Generated marker boundary did not interrupt");f.Active=true;Check(f.Calls.Disabled&&File.Exists(Marker(f)),"Generated disabled marker missing");return f;}catch{f.Dispose();throw;}}
 static IDictionary<string,object> Resume(SodaDesktopSigninUpgradeChecks.Fixture f,string expected=null,Action<string> step=null,Func<string,FileStream> create=null){expected=expected??SodaDesktopSigninUpgradeRecord.Digest(File.ReadAllBytes(Marker(f)));using(var state=new SodaDesktopSigninMaintenanceState(f.Paths,()=>f.Active,(p,a)=>true))using(var service=new SodaDesktopSigninUpgradeScm(f.Calls,()=>f.Active))return SodaDesktopSigninMaintenanceRecovery.Resume(Owner,f.OldHash,f.NewHash,expected,state,service,f.Barrier,p=>{Check(SodaDesktopSigninPackageNative.Absent(p),"Generated recovery directory adopted");Directory.CreateDirectory(p);},create??(p=>new FileStream(p,FileMode.CreateNew,FileAccess.ReadWrite,FileShare.None)),step);}
 static IDictionary<string,object> Restore(SodaDesktopSigninUpgradeChecks.Fixture f){using(var state=new SodaDesktopSigninMaintenanceState(f.Paths,()=>f.Active,(p,a)=>true))using(var service=new SodaDesktopSigninUpgradeScm(f.Calls,()=>f.Active))return SodaDesktopSigninMaintenanceRecovery.Restore(Owner,f.NewHash,state,service,f.Barrier);}
 static void CopyTree(string source,string target){Directory.CreateDirectory(target);foreach(string directory in Directory.GetDirectories(source,"*",SearchOption.AllDirectories))Directory.CreateDirectory(Path.Combine(target,directory.Substring(source.Length+1)));foreach(string file in Directory.GetFiles(source,"*",SearchOption.AllDirectories))File.Copy(file,Path.Combine(target,file.Substring(source.Length+1)));}
 public static void Run(){
  using(var f=Prepare()){
   byte[] original=File.ReadAllBytes(Marker(f));string hash=SodaDesktopSigninUpgradeRecord.Digest(original);var record=SodaDesktopSigninUpgradeRecord.Decode(original,Owner,f.OldHash,f.NewHash,hash);
   Refused(()=>Resume(f,new string('f',64)),"Wrong reviewed marker SHA accepted");Check(f.Calls.Manuals==0,"Wrong marker changed service");
   var value=(Dictionary<string,object>)new JavaScriptSerializer().DeserializeObject(System.Text.Encoding.UTF8.GetString(original));value["oldBoundarySha256"]=new string('f',64);byte[] changed=System.Text.Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(new SortedDictionary<string,object>(value,StringComparer.Ordinal)));File.WriteAllBytes(Marker(f),changed);Refused(()=>Resume(f),"Wrong old clean digest accepted");Check(f.Calls.Manuals==0,"Wrong old digest changed service");File.WriteAllBytes(Marker(f),original);
   string retained=Path.Combine(f.Root,"retained-original-code");Directory.Move(f.Paths.Code,retained);CopyTree(retained,f.Paths.Code);Refused(()=>Resume(f),"Replaced old directory identity accepted");Check(f.Calls.Manuals==0,"Replaced root changed service");Directory.Delete(f.Paths.Code,true);Directory.Move(retained,f.Paths.Code);
   using(var state=new SodaDesktopSigninMaintenanceState(f.Paths,()=>f.Active,(p,a)=>true)){state.OpenMarker(Owner,f.OldHash,f.NewHash,hash);using(var pin=f.Barrier())using(var exclusive=pin.Exclusive()){state.Exclusive=exclusive;using(var package=new SodaDesktopSigninUpgrade.Package(f.Paths.Code,Owner,f.OldHash,(p,a)=>true,state.Current))Check(package.Current(),"Generated old package pin missing");Directory.Move(f.Paths.Code,retained);CopyTree(retained,f.Paths.Code);string destination=Path.Combine(f.Paths.ProgramParent,record.CodeArchive);Refused(()=>state.Move(f.Paths.Code,destination,record.OldCode),"Released source replacement was moved");Check(!Directory.Exists(destination)&&Directory.Exists(f.Paths.Code),"Released replacement reached archive");Directory.Delete(f.Paths.Code,true);Directory.Move(retained,f.Paths.Code);}}
   foreach(bool dispose in new[]{false,true}){bool armed=false;SodaDesktopSigninMaintenanceState state=null;try{state=new SodaDesktopSigninMaintenanceState(f.Paths,()=>f.Active,(path,acl)=>{if(armed&&path==f.Paths.Code){if(dispose)state.Dispose();else f.Active=false;}return true;});state.OpenMarker(Owner,f.OldHash,f.NewHash,hash);using(var pin=f.Barrier())using(var exclusive=pin.Exclusive()){state.Exclusive=exclusive;armed=true;string destination=Path.Combine(f.Paths.ProgramParent,record.CodeArchive);Refused(()=>state.Move(f.Paths.Code,destination,record.OldCode),"Metadata revocation unexpectedly completed");armed=false;f.Active=true;Check(!Directory.Exists(destination)&&Directory.Exists(f.Paths.Code),"Metadata revoked source was moved");}}finally{armed=false;f.Active=true;if(state!=null)state.Dispose();}}
   foreach(string step in new[]{"code-archived","new-code-published","runs-archived"}){Refused(()=>Resume(f,step:at=>{if(at==step)f.Active=false;}),"Interrupted resume unexpectedly completed");f.Active=true;Check(f.Calls.Disabled&&f.Calls.Manuals==0&&File.Exists(Marker(f)),"Interrupted resume lost disabled marker");f.Preserved();}
   string runs=Path.Combine(f.Paths.Slot,"runs");Directory.CreateDirectory(runs);File.WriteAllText(Path.Combine(runs,"unknown"),"preserve");Refused(()=>Resume(f),"Unknown new-run residue accepted");Check(f.Calls.Manuals==0&&File.ReadAllText(Path.Combine(runs,"unknown"))=="preserve","Unknown new-run residue changed");File.Delete(Path.Combine(runs,"unknown"));Directory.Delete(runs);
   Refused(()=>Resume(f,create:p=>{using(var output=new FileStream(p,FileMode.CreateNew,FileAccess.ReadWrite,FileShare.None)){output.Write(new byte[]{7,8,9},0,3);output.Flush(true);}throw new IOException("Generated partial metadata write");}),"Partial metadata unexpectedly completed");Check(File.ReadAllBytes(Path.Combine(runs,"initial.writing")).Length==3&&f.Calls.Manuals==0,"Partial initial was changed");
   string incomplete=Path.Combine(f.Paths.Slot,"runs-incomplete-"+record.Id);Directory.CreateDirectory(incomplete);File.WriteAllText(Path.Combine(incomplete,"keep"),"preserve");Refused(()=>Resume(f),"Incomplete archive collision overwritten");Check(File.ReadAllText(Path.Combine(incomplete,"keep"))=="preserve"&&f.Calls.Manuals==0,"Incomplete collision changed");Directory.Delete(incomplete,true);
   var result=Resume(f);Check((string)result["state"]=="upgrade-resumed"&&!(bool)result["started"]&&f.Calls.Manuals==1&&!f.Calls.Disabled&&!File.Exists(Marker(f)),"Known transition did not resume without starting");byte[] bytes=File.ReadAllBytes(Path.Combine(incomplete,"initial.writing"));Check(bytes.Length==3&&bytes[0]==7&&bytes[1]==8&&bytes[2]==9,"Partial metadata bytes were not preserved");f.Preserved();
   using(var pin=f.Barrier()){Check(pin.Fingerprint==record.Barrier,"Resume replaced immutable barrier");using(var journal=new SodaDesktopSigninRunJournal(runs,Owner,f.NewHash,pin.Fingerprint,SodaDesktopSigninRunJournal.Role.Reader,()=>true,a=>true,new string[0]))Check(journal.CleanBoundary().RunId==record.NewRun,"Resumed new run differs from marker");using(var journal=new SodaDesktopSigninRunJournal(Path.Combine(f.Paths.Slot,record.RunArchive),Owner,f.OldHash,pin.Fingerprint,SodaDesktopSigninRunJournal.Role.Reader,()=>true,a=>true,new string[0]))Check(journal.CleanBoundary().Digest()==record.OldDigest,"Resumed old clean evidence changed");}
   f.Calls.Disabled=true;Check((string)Restore(f)["state"]=="clean-manual-restored"&&f.Calls.Manuals==2,"Marker-absent clean restoration failed");f.Preserved();
   using(var pin=f.Barrier())using(var exclusive=pin.Exclusive())using(var writer=new SodaDesktopSigninRunJournal(runs,Owner,f.NewHash,exclusive.Fingerprint,SodaDesktopSigninRunJournal.Role.Controller,()=>true,a=>true,new string[0])){long now=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();writer.Prepare(SodaDesktopSigninRunRecord.Build(new Dictionary<string,object>{{"version",1},{"purpose","desktop-signin-run"},{"kind","intent"},{"ownerSid",Owner},{"runId",Guid.NewGuid().ToString("D")},{"packageSha256",f.NewHash},{"barrierSha256",exclusive.Fingerprint},{"issuedAt",now},{"expiresAt",now+60000},{"mode","normal"}},Owner));}f.Calls.Disabled=true;Refused(()=>Restore(f),"Unclean current generation restored");Check(f.Calls.Manuals==2,"Unclean current state changed service");
  }
  var calls=new SodaDesktopSigninUpgradeChecks.Calls{Disabled=true};using(var service=new SodaDesktopSigninUpgradeScm(calls,()=>true)){Refused(()=>service.RestoreManual(()=>false),"Unproved recovery enabled service");Check(calls.Manuals==0,"Unproved recovery reached manual");}
  using(var f=Prepare()){
   Refused(()=>Resume(f,create:p=>{using(var output=new FileStream(p,FileMode.CreateNew,FileAccess.ReadWrite,FileShare.None)){}throw new IOException("Generated empty initial write");}),"Empty metadata unexpectedly completed");string runs=Path.Combine(f.Paths.Slot,"runs");Check(new FileInfo(Path.Combine(runs,"initial.writing")).Length==0,"Empty partial was not created");string hash=SodaDesktopSigninUpgradeRecord.Digest(File.ReadAllBytes(Marker(f)));var record=SodaDesktopSigninUpgradeRecord.Decode(File.ReadAllBytes(Marker(f)),Owner,f.OldHash,f.NewHash,hash);Resume(f);Check(new FileInfo(Path.Combine(f.Paths.Slot,"runs-incomplete-"+record.Id,"initial.writing")).Length==0&&f.Calls.Manuals==1,"Empty metadata was not preserved without execution");f.Preserved();
  }
  Console.WriteLine("signin_maintenance_recovery_generated_closed_resume_interruption_partial_preservation_and_clean_restore_passed");
 }
}
